// ============================================================
// RepeatInterleaveGrad kernel
// 分段归约算子: 沿 axis 将 y_grad 按 segment 分组求和
// 标量模式: segment 长度恒定 (r)
// 向量模式: segment 长度由 repeats tensor 指定
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelRepeatInterleaveGrad {
public:
    __aicore__ inline KernelRepeatInterleaveGrad() {}

    __aicore__ inline void Init(GM_ADDR y_grad, GM_ADDR repeats_data, GM_ADDR x_grad,
                                int64_t totalGroups, int64_t innerSize,
                                int64_t inAxisSize, int64_t outAxisSize,
                                int64_t dtypeSize, int64_t groupsPerCore,
                                int64_t tileLength,
                                int64_t scalarFlag, int64_t segLenScalar)
    {
        totalGroups_ = totalGroups;
        innerSize_ = innerSize;
        inAxisSize_ = inAxisSize;
        outAxisSize_ = outAxisSize;
        dtypeSize_ = dtypeSize;
        groupsPerCore_ = groupsPerCore;
        tileLength_ = tileLength;
        scalarFlag_ = scalarFlag;
        segLenScalar_ = segLenScalar;

        int64_t totalInputElems = static_cast<int64_t>(totalGroups_) * inAxisSize_ * innerSize_;
        yGm.SetGlobalBuffer((__gm__ T *)y_grad, totalInputElems > 0 ? totalInputElems : 1);
        repeatsGm.SetGlobalBuffer((__gm__ int32_t *)repeats_data, outAxisSize_ > 0 ? outAxisSize_ : 1);
        xGm.SetGlobalBuffer((__gm__ T *)x_grad, totalGroups_ * innerSize_ > 0 ? totalGroups_ * innerSize_ : 1);

        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength_ * sizeof(T));
        pipe.InitBuffer(accBuf, tileLength_ * sizeof(float));
        // FP16/BF16: extra FP32 cast buffer for input
        if constexpr (sizeof(T) != sizeof(float)) {
            pipe.InitBuffer(castFp32Buf, tileLength_ * sizeof(float));
        }
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength_ * sizeof(T));

        tileNum_ = (innerSize_ + tileLength_ - 1) / tileLength_;
        tailTileLength_ = innerSize_ - (tileNum_ - 1) * tileLength_;

        // For DataCopyPad alignment: align tail tile to 32B
        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        if (alignNum <= 0) alignNum = 1;
        alignedTailLen_ = ((tailTileLength_ + alignNum - 1) / alignNum) * alignNum;

        // For vector mode: small buffer to read repeats[n] from GM
        if (!scalarFlag_) {
            pipe.InitBuffer(segLenBuf, 1 * sizeof(int32_t));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        int64_t groupStart = blockIdx * groupsPerCore_;
        int64_t groupEnd = groupStart + groupsPerCore_;
        if (groupEnd > totalGroups_) {
            groupEnd = totalGroups_;
        }
        if (groupStart >= totalGroups_) {
            return;
        }

        // For vector mode, track cumulative offset within current batch
        int64_t curBatch = -1;
        int64_t cumOffset = 0;

        for (int64_t g = groupStart; g < groupEnd; g++) {
            int64_t b = g / outAxisSize_;
            int64_t n = g % outAxisSize_;

            // Reset cumOffset when entering a new batch
            if (static_cast<int32_t>(b) != curBatch) {
                curBatch = static_cast<int32_t>(b);
                cumOffset = 0;
            }

            int64_t segLen;
            int64_t inputOffsetInAxis;
            if (scalarFlag_) {
                segLen = segLenScalar_;
                inputOffsetInAxis = n * segLenScalar_;
            } else {
                // Read repeats[n] from GM
                LocalTensor<int32_t> segLenLocal = segLenBuf.Get<int32_t>();
                AscendC::DataCopyExtParams copyParams;
                copyParams.blockCount = 1;
                copyParams.blockLen = static_cast<uint32_t>(sizeof(int32_t));
                copyParams.srcStride = 0;
                copyParams.dstStride = 0;
                AscendC::DataCopyPadExtParams<int32_t> padParams;
                padParams.isPad = false;
                AscendC::DataCopyPad(segLenLocal, repeatsGm[n], copyParams, padParams);
                AscendC::PipeBarrier<AscendC::PIPE_ALL>();
                segLen = static_cast<int64_t>(segLenLocal.GetValue(0));
                inputOffsetInAxis = cumOffset;
            }

            int64_t inAxisBase = b * inAxisSize_ + inputOffsetInAxis;
            int64_t outputBase = (b * outAxisSize_ + n) * innerSize_;

            // Process tiles along innerSize
            for (int64_t t = 0; t < tileNum_; t++) {
                int64_t curLen;
                int64_t copyLen;
                if (t < tileNum_ - 1) {
                    curLen = tileLength_;
                    copyLen = tileLength_;
                } else {
                    curLen = tailTileLength_;
                    copyLen = alignedTailLen_;
                }
                int64_t tileInnerOffset = t * tileLength_;

                // Init accumulator to zero
                LocalTensor<float> accLocal = accBuf.Get<float>();
                AscendC::Duplicate<float>(accLocal, 0.0f, copyLen);

                // Sum all segments for this tile
                for (int64_t s = 0; s < segLen; s++) {
                    // CopyIn: GM → UB
                    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
                    AscendC::DataCopyExtParams inParams;
                    inParams.blockCount = 1;
                    inParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
                    inParams.srcStride = 0;
                    inParams.dstStride = 0;
                    AscendC::DataCopyPadExtParams<T> inPadParams;
                    inPadParams.isPad = false;
                    AscendC::DataCopyPad(inLocal,
                        yGm[(inAxisBase + s) * innerSize_ + tileInnerOffset],
                        inParams, inPadParams);
                    inQueue.EnQue(inLocal);

                    // Compute: DeQue → Cast(if needed) → Add to accumulator
                    LocalTensor<T> inReady = inQueue.DeQue<T>();
                    if constexpr (sizeof(T) != sizeof(float)) {
                        LocalTensor<float> castLocal = castFp32Buf.Get<float>();
                        AscendC::Cast(castLocal, inReady, AscendC::RoundMode::CAST_NONE, curLen);
                        AscendC::Add(accLocal, accLocal, castLocal, curLen);
                    } else {
                        AscendC::Add(accLocal, accLocal, inReady, curLen);
                    }
                    inQueue.FreeTensor(inReady);
                }

                // CopyOut: UB → GM
                LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
                if constexpr (sizeof(T) != sizeof(float)) {
                    // Cast FP32 accumulator → output dtype
                    AscendC::Cast(outLocal, accLocal, AscendC::RoundMode::CAST_ROUND, curLen);
                } else {
                    // Direct copy FP32 → FP32
                    AscendC::DataCopy(outLocal, accLocal, curLen);
                }
                outQueue.EnQue(outLocal);

                LocalTensor<T> outReady = outQueue.DeQue<T>();
                AscendC::DataCopyExtParams outParams;
                outParams.blockCount = 1;
                outParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
                outParams.srcStride = 0;
                outParams.dstStride = 0;
                AscendC::DataCopyPad(xGm[outputBase + tileInnerOffset], outReady, outParams);
                outQueue.FreeTensor(outReady);
            }

            if (!scalarFlag_) {
                cumOffset += segLen;
            }
        }
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castFp32Buf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> segLenBuf;

    AscendC::GlobalTensor<T> yGm;
    AscendC::GlobalTensor<int32_t> repeatsGm;
    AscendC::GlobalTensor<T> xGm;

    int64_t totalGroups_ = 0;
    int64_t innerSize_ = 0;
    int64_t inAxisSize_ = 0;
    int64_t outAxisSize_ = 0;
    int64_t dtypeSize_ = 0;
    int64_t groupsPerCore_ = 0;
    int64_t tileLength_ = 0;
    int64_t scalarFlag_ = 0;
    int64_t segLenScalar_ = 0;

    int64_t tileNum_ = 0;
    int64_t tailTileLength_ = 0;
    int64_t alignedTailLen_ = 0;
};

extern "C" __global__ __aicore__ void repeat_interleave_grad(
    GM_ADDR y_grad, GM_ADDR repeats_data, GM_ADDR x_grad,
    int64_t totalGroups, int64_t innerSize,
    int64_t inAxisSize, int64_t outAxisSize,
    int64_t dtypeSize, int64_t groupsPerCore,
    int64_t tileLength,
    int64_t scalarFlag, int64_t segLenScalar)
{
    if (dtypeSize == 2) {
        KernelRepeatInterleaveGrad<AscendC::half> op;
        op.Init(y_grad, repeats_data, x_grad,
                totalGroups, innerSize, inAxisSize, outAxisSize,
                dtypeSize, groupsPerCore, tileLength,
                scalarFlag, segLenScalar);
        op.Process();
    } else {
        KernelRepeatInterleaveGrad<float> op;
        op.Init(y_grad, repeats_data, x_grad,
                totalGroups, innerSize, inAxisSize, outAxisSize,
                dtypeSize, groupsPerCore, tileLength,
                scalarFlag, segLenScalar);
        op.Process();
    }
}
