// ============================================================
// RepeatInterleaveGrad Host 端
// tiling 计算 + EXEC_KERNEL_CMD 启动
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_repeat_interleave_grad.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor repeat_interleave_grad(const at::Tensor &y_grad,
                                  const at::Tensor &repeats,
                                  int64_t axis)
{
    // ---- 输入校验 ----
    TORCH_CHECK(y_grad.device().type() == at::DeviceType::PrivateUse1,
                "repeat_interleave_grad: y_grad must be on NPU device");
    TORCH_CHECK(y_grad.scalar_type() == at::kHalf ||
                y_grad.scalar_type() == at::kBFloat16 ||
                y_grad.scalar_type() == at::kFloat,
                "repeat_interleave_grad: only float16/bfloat16/float32 are supported");

    int64_t ndim = y_grad.dim();
    if (axis < 0) axis += ndim;
    TORCH_CHECK(axis >= 0 && axis < ndim,
                "repeat_interleave_grad: axis out of range");

    // ---- 维度分解: [B, N_in, innerSize] ----
    int64_t batch = 1;
    for (int64_t i = 0; i < axis; i++) batch *= y_grad.size(i);

    int64_t inAxisSize = y_grad.size(axis);

    int64_t innerSize = 1;
    for (int64_t i = axis + 1; i < ndim; i++) innerSize *= y_grad.size(i);

    int64_t dtypeSize = y_grad.element_size();

    // ---- 标量/向量模式判定 ----
    auto repeatsCpu = repeats.cpu();
    bool isScalar = (repeatsCpu.numel() == 1);
    int64_t rVal = 0;
    int64_t outAxisSize = 0;
    at::Tensor repeatsInt32Gpu;

    if (isScalar) {
        rVal = static_cast<int64_t>(repeatsCpu.item<int64_t>());
        if (rVal == 0) {
            // 全零输出
            return at::zeros_like(y_grad);
        }
        outAxisSize = inAxisSize / rVal;
        // 创建空 placeholder tensor for repeats_data (scalar 模式不使用)
        repeatsInt32Gpu = at::empty({0},
            at::TensorOptions().dtype(at::kInt).device(y_grad.device()));
    } else {
        outAxisSize = repeats.size(0);
        // 将 repeats 转为 int32 (若为 int64)
        if (repeats.scalar_type() != at::kInt) {
            repeatsInt32Gpu = repeats.to(at::kInt).contiguous();
        } else {
            repeatsInt32Gpu = repeats.contiguous();
        }
    }

    // ---- 输出 tensor ----
    // output shape: same as y_grad but axis dim = outAxisSize
    auto outputShape = y_grad.sizes().vec();
    outputShape[axis] = outAxisSize;
    auto x_grad = at::empty(outputShape, y_grad.options());

    int64_t totalGroups = batch * outAxisSize;
    if (totalGroups == 0) return x_grad;
    int64_t totalLength = totalGroups * innerSize;
    if (totalLength == 0) return x_grad;

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 Tiling (核间: 按输出组分配的核) ----
    // Each core processes groupsPerCore output groups
    int64_t groupsPerCore = (totalGroups + coreNum - 1) / coreNum;
    if (groupsPerCore < 1) groupsPerCore = 1;

    // Block-level alignment: align groupsPerCore to cache line
    int64_t alignElementsBlock = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    if (alignElementsBlock <= 0) alignElementsBlock = 1;
    int64_t groupsPerCoreAlign = ((groupsPerCore + alignElementsBlock - 1) / alignElementsBlock)
                                  * alignElementsBlock;

    int64_t usedCoreNum = (totalGroups + groupsPerCoreAlign - 1) / groupsPerCoreAlign;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    // ---- UB 级 Tiling (核内: 沿 innerSize 分 tile) ----
    // bufferCoefficient from design doc: fp32=20, fp16/bf16=16
    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
    if (bufferCoefficient <= 0) bufferCoefficient = 1;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;

    int64_t alignElementsUB = 32 / dtypeSize;
    if (alignElementsUB <= 0) alignElementsUB = 1;
    int64_t tileLength = (maxTileElements / alignElementsUB) * alignElementsUB;
    if (tileLength <= 0) tileLength = alignElementsUB;

    // Clamp tileLength to innerSize
    if (tileLength > innerSize) {
        tileLength = innerSize;
    }

    // ---- Launch kernel ----
