    int64_t scalarFlagVal = isScalar ? 1 : 0;

    // All EXEC_KERNEL_CMD args must be lvalues
    int64_t groupsPerCoreLval = groupsPerCore;
    int64_t tileLenLval = tileLength;
    int64_t segLenScalarLval = rVal;

    EXEC_KERNEL_CMD(repeat_interleave_grad, blockDim,
                    y_grad, repeatsInt32Gpu, x_grad,
                    totalGroups, innerSize, inAxisSize, outAxisSize,
                    dtypeSize, groupsPerCoreLval, tileLenLval,
                    scalarFlagVal, segLenScalarLval);

    return x_grad;
}

