11	// ============================================================
12	// RepeatInterleaveGrad kernel
13	// 分段归约算子: 沿 axis 将 y_grad 按 segment 分组求和
14	// 标量模式: segment 长度恒定 (r)
15	// 向量模式: segment 长度由 repeats tensor 指定
16	// ============================================================
17	
18	#include "kernel_operator.h"
19	
20	constexpr int32_t BUFFER_NUM = 2;
21	
22	template <typename T>
23	class KernelRepeatInterleaveGrad {
24	public:
25	    __aicore__ inline KernelRepeatInterleaveGrad() {}
26	
27	    __aicore__ inline void Init(GM_ADDR y_grad, GM_ADDR repeats_data, GM_ADDR x_grad,
28	                                int64_t totalGroups, int64_t innerSize,
29	                                int64_t inAxisSize, int64_t outAxisSize,
30	                                int64_t dtypeSize, int64_t groupsPerCore,
31	                                int64_t tileLength,
32	                                int64_t scalarFlag, int64_t segLenScalar)
33	    {
34	        totalGroups_ = totalGroups;
35	        innerSize_ = innerSize;
36	        inAxisSize_ = inAxisSize;
37	        outAxisSize_ = outAxisSize;
38	        dtypeSize_ = dtypeSize;
39	        groupsPerCore_ = groupsPerCore;
40	        tileLength_ = tileLength;
41	        scalarFlag_ = scalarFlag;
42	        segLenScalar_ = segLenScalar;
43	
44	        int64_t totalInputElems = static_cast<int64_t>(totalGroups_) * inAxisSize_ * innerSize_;
45	        yGm.SetGlobalBuffer((__gm__ T *)y_grad, totalInputElems > 0 ? totalInputElems : 1);
46	        repeatsGm.SetGlobalBuffer((__gm__ int32_t *)repeats_data, outAxisSize_ > 0 ? outAxisSize_ : 1);
47	        xGm.SetGlobalBuffer((__gm__ T *)x_grad, totalGroups_ * innerSize_ > 0 ? totalGroups_ * innerSize_ : 1);
48	
49	        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength_ * sizeof(T));
50	        pipe.InitBuffer(accBuf, tileLength_ * sizeof(float));
51	        // FP16/BF16: extra FP32 cast buffer for input
52	        if constexpr (sizeof(T) != sizeof(float)) {
53	            pipe.InitBuffer(castFp32Buf, tileLength_ * sizeof(float));
54	        }
55	        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength_ * sizeof(T));
56	
57	        tileNum_ = (innerSize_ + tileLength_ - 1) / tileLength_;
58	        tailTileLength_ = innerSize_ - (tileNum_ - 1) * tileLength_;
59	
60	        // For DataCopyPad alignment: align tail tile to 32B
61	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
62	        if (alignNum <= 0) alignNum = 1;
63	        alignedTailLen_ = ((tailTileLength_ + alignNum - 1) / alignNum) * alignNum;
64	
65	        // For vector mode: small buffer to read repeats[n] from GM
66	        if (!scalarFlag_) {
67	            pipe.InitBuffer(segLenBuf, 1 * sizeof(int32_t));
68	        }
69	    }
70	
71	    __aicore__ inline void Process()
72	    {
73	        int64_t blockIdx = AscendC::GetBlockIdx();
74	        int64_t groupStart = blockIdx * groupsPerCore_;
75	        int64_t groupEnd = groupStart + groupsPerCore_;
76	        if (groupEnd > totalGroups_) {
77	            groupEnd = totalGroups_;
78	        }
79	        if (groupStart >= totalGroups_) {
80	            return;
81	        }
82	
83	        // For vector mode, track cumulative offset within current batch
84	        int64_t curBatch = -1;
85	        int64_t cumOffset = 0;
86	
87	        for (int64_t g = groupStart; g < groupEnd; g++) {
88	            int64_t b = g / outAxisSize_;
89	            int64_t n = g % outAxisSize_;
90	
91	            // Reset cumOffset when entering a new batch
92	            if (static_cast<int32_t>(b) != curBatch) {
93	                curBatch = static_cast<int32_t>(b);
94	                cumOffset = 0;
95	            }
96	
97	            int64_t segLen;
98	            int64_t inputOffsetInAxis;
99	            if (scalarFlag_) {
100	                segLen = segLenScalar_;
101	                inputOffsetInAxis = n * segLenScalar_;
102	            } else {
103	                // Read repeats[n] from GM
104	                LocalTensor<int32_t> segLenLocal = segLenBuf.Get<int32_t>();
105	                AscendC::DataCopyExtParams copyParams;
106	                copyParams.blockCount = 1;
107	                copyParams.blockLen = static_cast<uint32_t>(sizeof(int32_t));
108	                copyParams.srcStride = 0;
109	                copyParams.dstStride = 0;
110	                AscendC::DataCopyPadExtParams<int32_t> padParams;
111	                padParams.isPad = false;
112	                AscendC::DataCopyPad(segLenLocal, repeatsGm[n], copyParams, padParams);
113	                AscendC::PipeBarrier<AscendC::PIPE_ALL>();
114	                segLen = static_cast<int64_t>(segLenLocal.GetValue(0));
115	                inputOffsetInAxis = cumOffset;
116	            }
117	
118	            int64_t inAxisBase = b * inAxisSize_ + inputOffsetInAxis;
119	            int64_t outputBase = (b * outAxisSize_ + n) * innerSize_;
120	
121	            // Process tiles along innerSize
122	            for (int64_t t = 0; t < tileNum_; t++) {
123	                int64_t curLen;
124	                int64_t copyLen;
125	                if (t < tileNum_ - 1) {
126	                    curLen = tileLength_;
127	                    copyLen = tileLength_;
128	                } else {
129	                    curLen = tailTileLength_;
130	                    copyLen = alignedTailLen_;
131	                }
132	                int64_t tileInnerOffset = t * tileLength_;
133	
134	                // Init accumulator to zero
135	                LocalTensor<float> accLocal = accBuf.Get<float>();
136	                AscendC::Duplicate<float>(accLocal, 0.0f, copyLen);
137	
138	                // Sum all segments for this tile
139	                for (int64_t s = 0; s < segLen; s++) {
140	                    // CopyIn: GM → UB
141	                    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
142	                    AscendC::DataCopyExtParams inParams;
143	                    inParams.blockCount = 1;
144	                    inParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
145	                    inParams.srcStride = 0;
146	                    inParams.dstStride = 0;
147	                    AscendC::DataCopyPadExtParams<T> inPadParams;
148	                    inPadParams.isPad = false;
149	                    AscendC::DataCopyPad(inLocal,
150	                        yGm[(inAxisBase + s) * innerSize_ + tileInnerOffset],
151	                        inParams, inPadParams);
152	                    inQueue.EnQue(inLocal);
153	
154	                    // Compute: DeQue → Cast(if needed) → Add to accumulator
155	                    LocalTensor<T> inReady = inQueue.DeQue<T>();
156	                    if constexpr (sizeof(T) != sizeof(float)) {
157	                        LocalTensor<float> castLocal = castFp32Buf.Get<float>();
158	                        AscendC::Cast(castLocal, inReady, AscendC::RoundMode::CAST_NONE, curLen);
159	                        AscendC::Add(accLocal, accLocal, castLocal, curLen);
160	                    } else {
161	                        AscendC::Add(accLocal, accLocal, inReady, curLen);
162	                    }
163	                    inQueue.FreeTensor(inReady);
164	                }
165	
166	                // CopyOut: UB → GM
167	                LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
168	                if constexpr (sizeof(T) != sizeof(float)) {
169	                    // Cast FP32 accumulator → output dtype
170	                    AscendC::Cast(outLocal, accLocal, AscendC::RoundMode::CAST_ROUND, curLen);
171	                } else {
172	                    // Direct copy FP32 → FP32
173	                    AscendC::DataCopy(outLocal, accLocal, curLen);
174	                }
175	                outQueue.EnQue(outLocal);
176	
177	                LocalTensor<T> outReady = outQueue.DeQue<T>();
178	                AscendC::DataCopyExtParams outParams;
179	                outParams.blockCount = 1;
180	                outParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
181	                outParams.srcStride = 0;
182	                outParams.dstStride = 0;
183	                AscendC::DataCopyPad(xGm[outputBase + tileInnerOffset], outReady, outParams);
184	                outQueue.FreeTensor(outReady);
185	            }
186	
187	            if (!scalarFlag_) {
188	                cumOffset += segLen;
189	            }
190	        }
191	    }
192	
193	private:
194	    AscendC::TPipe pipe;
195	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue;
196	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
197	    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf;
198	    AscendC::TBuf<AscendC::TPosition::VECCALC> castFp32Buf;
199	    AscendC::TBuf<AscendC::TPosition::VECCALC> segLenBuf;
200	
201	    AscendC::GlobalTensor<T> yGm;
202	    AscendC::GlobalTensor<int32_t> repeatsGm;
203	    AscendC::GlobalTensor<T> xGm;
204	
205	    int64_t totalGroups_ = 0;
206	    int64_t innerSize_ = 0;
207	    int64_t inAxisSize_ = 0;
208	    int64_t outAxisSize_ = 0;
209	    int64_t dtypeSize_ = 0;
210	    int64_t groupsPerCore_ = 0;
211	    int64_t tileLength_ = 0;
