11	// ============================================================
12	// RepeatInterleaveGrad kernel
13	// Segmented sum reduction: groups elements along axis by repeats
14	// Scalar mode: constant segment length r
15	// Vector mode: varying segment lengths from repeats tensor
16	// ============================================================
17	
18	#include "kernel_operator.h"
19	
20	using namespace AscendC;
21	
22	constexpr int32_t BUFFER_NUM = 2;
23	
24	template <typename T>
25	class KernelRepeatInterleaveGrad {
26	public:
27	    __aicore__ inline KernelRepeatInterleaveGrad() {}
28	
29	    __aicore__ inline void Init(GM_ADDR y_grad, GM_ADDR repeats_data, GM_ADDR x_grad,
30	                                int64_t totalGroups, int64_t innerSize,
31	                                int64_t inAxisSize, int64_t outAxisSize,
32	                                int64_t dtypeSize, int64_t groupsPerCore,
33	                                int64_t tileLength,
34	                                int64_t scalarFlag, int64_t segLenScalar)
35	    {
36	        totalGroups_ = totalGroups;
37	        innerSize_ = innerSize;
38	        inAxisSize_ = inAxisSize;
39	        outAxisSize_ = outAxisSize;
40	        dtypeSize_ = dtypeSize;
41	        groupsPerCore_ = groupsPerCore;
42	        tileLength_ = tileLength;
43	        scalarFlag_ = scalarFlag;
44	        segLenScalar_ = segLenScalar;
45	
46	        int64_t totalInputElems = totalGroups_ * inAxisSize_ * innerSize_;
47	        yGm.SetGlobalBuffer((__gm__ T *)y_grad, totalInputElems > 0 ? totalInputElems : 1);
48	        repeatsGm.SetGlobalBuffer((__gm__ int32_t *)repeats_data, outAxisSize_ > 0 ? outAxisSize_ : 1);
49	        xGm.SetGlobalBuffer((__gm__ T *)x_grad, totalGroups_ * innerSize_ > 0 ? totalGroups_ * innerSize_ : 1);
50	
51	        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength_ * sizeof(T));
52	        pipe.InitBuffer(accBuf, tileLength_ * sizeof(float));
53	        // FP16/BF16: extra FP32 cast buffer for input
54	        if constexpr (sizeof(T) != sizeof(float)) {
55	            pipe.InitBuffer(castFp32Buf, tileLength_ * sizeof(float));
56	        }
57	        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength_ * sizeof(T));
58	
59	        tileNum_ = (innerSize_ + tileLength_ - 1) / tileLength_;
60	        tailTileLength_ = innerSize_ - (tileNum_ - 1) * tileLength_;
61	
62	        // Align tail tile to 32B for DataCopyPad
63	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
64	        if (alignNum <= 0) alignNum = 1;
65	        alignedTailLen_ = ((tailTileLength_ + alignNum - 1) / alignNum) * alignNum;
66	
67	        // Vector mode: small buffer to read repeats[n] from GM
68	        if (!scalarFlag_) {
69	            pipe.InitBuffer(segLenBuf, 1 * sizeof(int32_t));
70	        }
71	    }
72	
73	    __aicore__ inline void Process()
74	    {
75	        int64_t blockIdx = GetBlockIdx();
76	        int64_t groupStart = blockIdx * groupsPerCore_;
77	        int64_t groupEnd = groupStart + groupsPerCore_;
78	        if (groupEnd > totalGroups_) {
79	            groupEnd = totalGroups_;
80	        }
81	        if (groupStart >= totalGroups_) {
82	            return;
83	        }
84	
85	        int64_t curBatch = -1;
86	        int64_t cumOffset = 0;
87	
88	        for (int64_t g = groupStart; g < groupEnd; g++) {
89	            int64_t b = g / outAxisSize_;
90	            int64_t n = g % outAxisSize_;
91	
92	            if (b != curBatch) {
93	                curBatch = b;
94	                cumOffset = 0;
95	            }
96	
97	            int64_t segLen;
98	            int64_t inputOffsetInAxis;
99	            if (scalarFlag_ != 0) {
100	                segLen = segLenScalar_;
101	                inputOffsetInAxis = n * segLenScalar_;
102	            } else {
103	                // Read repeats[n] from GM
104	                LocalTensor<int32_t> segLenLocal = segLenBuf.Get<int32_t>();
105	                DataCopyExtParams copyParams;
106	                copyParams.blockCount = 1;
107	                copyParams.blockLen = static_cast<uint32_t>(sizeof(int32_t));
108	                copyParams.srcStride = 0;
109	                copyParams.dstStride = 0;
110	                DataCopyPadExtParams<int32_t> padParams;
111	                padParams.isPad = false;
112	                DataCopyPad(segLenLocal, repeatsGm[n], copyParams, padParams);
113	                PipeBarrier<PIPE_ALL>();
114	                segLen = static_cast<int64_t>(segLenLocal.GetValue(0));
115	                inputOffsetInAxis = cumOffset;
116	            }
117	
118	            int64_t inAxisBase = b * inAxisSize_ + inputOffsetInAxis;
119	            int64_t outputBase = (b * outAxisSize_ + n) * innerSize_;
120	
121	            // Process tiles along innerSize
122	            for (int64_t t = 0; t < tileNum_; t++) {
123	                int64_t curLen;
124	                int64_t copyLen;
125	                if (t < tileNum_ - 1) {
126	                    curLen = tileLength_;
127	                    copyLen = tileLength_;
128	                } else {
129	                    curLen = tailTileLength_;
130	                    copyLen = alignedTailLen_;
131	                }
132	                int64_t tileInnerOffset = t * tileLength_;
133	
134	                // Init accumulator to zero
135	                LocalTensor<float> accLocal = accBuf.Get<float>();
136	                Duplicate<float>(accLocal, 0.0f, copyLen);
137	
138	                // Sum all segments for this tile
139	                for (int64_t s = 0; s < segLen; s++) {
140	                    // CopyIn: GM → UB
141	                    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
142	                    DataCopyExtParams inParams;
143	                    inParams.blockCount = 1;
144	                    inParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
145	                    inParams.srcStride = 0;
146	                    inParams.dstStride = 0;
147	                    DataCopyPadExtParams<T> inPadParams;
148	                    inPadParams.isPad = false;
149	                    DataCopyPad(inLocal,
150	                        yGm[(inAxisBase + s) * innerSize_ + tileInnerOffset],
151	                        inParams, inPadParams);
152	                    inQueue.EnQue(inLocal);
153	
154	                    // Compute: DeQue → Cast (if needed) → Add to accumulator
155	                    LocalTensor<T> inReady = inQueue.DeQue<T>();
156	                    if constexpr (sizeof(T) != sizeof(float)) {
157	                        LocalTensor<float> inFp32 = castFp32Buf.Get<float>();
158	                        Cast(inFp32, inReady, RoundMode::CAST_NONE, curLen);
159	                        Add(accLocal, accLocal, inFp32, curLen);
160	                    } else {
161	                        Add(accLocal, accLocal, inReady, curLen);
162	                    }
163	                    inQueue.FreeTensor(inReady);
164	                }
165	
166	                // CopyOut: UB → GM
167	                if constexpr (sizeof(T) != sizeof(float)) {
168	                    // FP16/BF16: Cast FP32 accumulator → output dtype
169	                    LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
170	                    Cast(outLocal, accLocal, RoundMode::CAST_ROUND, curLen);
171	                    outQueue.EnQue(outLocal);
172	                } else {
173	                    // FP32: copy FP32 accumulator to output
174	                    LocalTensor<float> outLocalFp32 = outQueue.AllocTensor<float>();
175	                    Duplicate<float>(outLocalFp32, 0.0f, copyLen);
176	                    Add(outLocalFp32, outLocalFp32, accLocal, curLen);
177	                    outQueue.EnQue(outLocalFp32);
178	                }
179	
180	                if constexpr (sizeof(T) != sizeof(float)) {
181	                    LocalTensor<T> outReady = outQueue.DeQue<T>();
182	                    DataCopyExtParams outParams;
183	                    outParams.blockCount = 1;
184	                    outParams.blockLen = static_cast<uint32_t>(curLen * sizeof(T));
185	                    outParams.srcStride = 0;
186	                    outParams.dstStride = 0;
187	                    DataCopyPad(xGm[outputBase + tileInnerOffset], outReady, outParams);
188	                    outQueue.FreeTensor(outReady);
189	                } else {
190	                    LocalTensor<float> outReady = outQueue.DeQue<float>();
191	                    DataCopyExtParams outParams;
192	                    outParams.blockCount = 1;
193	                    outParams.blockLen = static_cast<uint32_t>(curLen * sizeof(float));
194	                    outParams.srcStride = 0;
195	                    outParams.dstStride = 0;
196	                    DataCopyPad(xGm[outputBase + tileInnerOffset], outReady, outParams);
197	                    outQueue.FreeTensor(outReady);
198	                }
199	            }
200	
201	            if (scalarFlag_ == 0) {
202	                cumOffset += segLen;
203	            }
204	        }
205	    }
206	
207	private:
208	    TPipe pipe;
209	    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
210	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;
211	    TBuf<TPosition::VECCALC> accBuf;
212	    TBuf<TPosition::VECCALC> castFp32Buf;
213	    TBuf<TPosition::VECCALC> segLenBuf;
214	
215	    GlobalTensor<T> yGm;
216	    GlobalTensor<int32_t> repeatsGm;
217	    GlobalTensor<T> xGm;
218	
219	    int64_t totalGroups_ = 0;
220	    int64_t innerSize_ = 0;
221	    int64_t inAxisSize_ = 0;
222	    int64_t outAxisSize_ = 0;
223	    int64_t dtypeSize_ = 0;
224	    int64_t groupsPerCore_ = 0;
225	    int64_t tileLength_ = 0;
226	    int64_t scalarFlag_ = 0;
227	    int64_t segLenScalar_ = 0;
228	
229	    int64_t tileNum_ = 0;
230	    int64_t tailTileLength_ = 0;
231	    int64_t alignedTailLen_ = 0;
232	};
233	
234	extern "C" __global__ __aicore__ void repeat_interleave_grad(
235	    GM_ADDR y_grad, GM_ADDR repeats_data, GM_ADDR x_grad,
236	    int64_t totalGroups, int64_t innerSize,
237	    int64_t inAxisSize, int64_t outAxisSize,
238	    int64_t dtypeSize, int64_t groupsPerCore,
239	    int64_t tileLength,
240	    int64_t scalarFlag, int64_t segLenScalar)
241	{
242	    if (dtypeSize == 2) {
243	        KernelRepeatInterleaveGrad<half> op;
244	        op.Init(y_grad, repeats_data, x_grad,
245	                totalGroups, innerSize, inAxisSize, outAxisSize,
246	                dtypeSize, groupsPerCore, tileLength,
247	                scalarFlag, segLenScalar);
248	        op.Process();
249	    } else {
250	        KernelRepeatInterleaveGrad<float> op;
251	        op.Init(y_grad, repeats_data, x_grad,
252	                totalGroups, innerSize, inAxisSize, outAxisSize,
253	                dtypeSize, groupsPerCore, tileLength,
254	                scalarFlag, segLenScalar);
255	        op.Process();
256	    }
257	}
